function totalThrough(i){let n=0;for(let j=0;j<=i;j++)n+=calc(j).saved;return n}
function all(){return db.months.map((_,i)=>calc(i))}
function showToast(s){const el=document.getElementById('toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function populateMonths(){['dashMonth','salaryMonth','budgetMonth','reportMonth','debtMonth'].forEach(id=>{const el=document.getElementById(id);if(!el)return;el.innerHTML=MONTHS.map((m,i)=>`<option value="${i}">${m} ${YEAR}</option>`).join('');el.value=selected})}
function setMonth(i){selected=Math.max(0,Math.min(11,Number(i)));['dashMonth','salaryMonth','budgetMonth','debtMonth'].forEach(id=>{const el=document.getElementById(id);if(el)el.value=selected});const reportMonth=document.getElementById('reportMonth');if(reportMonth)reportMonth.value=selected;document.getElementById('topMonth').textContent=MONTHS[selected]+' '+YEAR;renderAll()}
function go(page){if(page==='leave'||page==='reports')page='settings';activePage=page;document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id==='page-'+page));document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));document.querySelectorAll('#mobileNav button').forEach(x=>x.classList.toggle('active',x.dataset.page===page));renderAll();window.scrollTo({top:0,behavior:'smooth'})}
function buildNav(){const names=[['dashboard','Overview'],['salary','Salary'],['budget','Budget'],['debts','Loans'],['savings','Savings'],['settings','Settings']];document.getElementById('mobileNav').innerHTML=names.map(([p,n])=>`<button data-page="${p}" class="${p===activePage?'active':''}">${n}</button>`).join('');document.getElementById('mobileNav').addEventListener('click',e=>{const b=e.target.closest('button[data-page]');if(b)go(b.dataset.page)})}
function renderDashboard(){const c=calc(selected);document.getElementById('kpiSalary').textContent=money(c.net);document.getElementById('kpiDays').textContent=`${c.days} paid working days`;document.getElementById('kpiExpenses').textContent=money(c.expenses);document.getElementById('kpiExpenseMvr').textContent=`${mvr(c.mvr)} local expenses`;document.getElementById('kpiSavings').textContent=money(c.saved);document.getElementById('kpiBalance').textContent=money(openingBalances().usd+totalThrough(selected));const carry=document.getElementById('carriedForward');if(carry)carry.textContent=money(openingBalances().usd);const mvrCarry=document.getElementById('mvrCarriedForward');if(mvrCarry)mvrCarry.textContent=mvr(openingBalances().mvr);document.getElementById('snapshotMonth').textContent=MONTHS[selected]+' '+YEAR;document.getElementById('snapGross').textContent=money(c.gross);document.getElementById('snapDeduct').textContent=money(current().salary.active?c.pension+num(current().salary.social)+c.extraDeduction:0);document.getElementById('snapUsd').textContent=money(c.usd);document.getElementById('snapMvr').textContent=money(c.mvrUsd);document.getElementById('snapExchangeNeeded').textContent=money(c.exchangeNeeded);document.getElementById('snapSaved').textContent=money(c.saved);document.getElementById('snapOtherIncome').textContent=money(c.otherIncomeUsd);renderCategories(c);drawChart()}
function renderCategories(c){const cats={};current().expenses.forEach(e=>{const v=toUsd(e.amount,e.currency,current().budget.rate);cats[e.category]=(cats[e.category]||0)+v});const entries=Object.entries(cats).sort((a,b)=>b[1]-a[1]),max=Math.max(1,...entries.map(x=>x[1]));document.getElementById('categoryList').innerHTML=entries.length?entries.map(([n,v])=>`<div class="category-row"><span>${escapeHtml(n)}</span><div class="bar-track"><div class="bar-fill" style="width:${v/max*100}%"></div></div><b>${money(v)}</b></div>`).join(''):'<div class="empty-state">Add expenses to see your breakdown.</div>'}
function drawChart(){const canvas=document.getElementById('savingsChart');if(!canvas)return;const ctx=canvas.getContext('2d'),w=canvas.clientWidth||500,h=canvas.clientHeight||220,dpr=window.devicePixelRatio||1;canvas.width=w*dpr;canvas.height=h*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);const vals=all().map(x=>x.saved),max=Math.max(100,...vals.map(v=>Math.abs(v))),left=12,right=8,top=12,bottom=30,chartH=h-top-bottom,chartW=w-left-right;ctx.strokeStyle='#edf0f5';ctx.lineWidth=1;for(let k=0;k<4;k++){const y=top+k*chartH/3;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(w-right,y);ctx.stroke()}const zero=top+chartH/2;ctx.strokeStyle='#d8dde7';ctx.beginPath();ctx.moveTo(left,zero);ctx.lineTo(w-right,zero);ctx.stroke();const slot=chartW/12,bw=Math.min(19,slot*.54);vals.forEach((v,i)=>{const bh=Math.abs(v)/max*(chartH*.43),x=left+i*slot+(slot-bw)/2,y=v>=0?zero-bh:zero;ctx.fillStyle=v>=0?'#5777d6':'#d98282';ctx.beginPath();if(ctx.roundRect)ctx.roundRect(x,y,bw,Math.max(2,bh),4);else ctx.rect(x,y,bw,Math.max(2,bh));ctx.fill();ctx.fillStyle='#8993a3';ctx.font='9px -apple-system, sans-serif';ctx.textAlign='center';ctx.fillText(MONTHS[i].slice(0,3),x+bw/2,h-9)})}
function renderSalary(){const s=current().salary,c=calc(selected);['basePay','dailyRate','telephone','pensionRate','socialFund','extraDeduction','otherAllowances'].forEach((id,k)=>document.getElementById(id).value=[s.base,s.daily,s.telephone,s.pension,s.social,num(s.extraDeduction),num(s.otherAllowances)][k]);document.getElementById('manualDays').checked=!!s.manual;document.getElementById('workedDays').value=s.manual?s.daysOverride:c.days;document.getElementById('workedDays').disabled=!s.manual;document.getElementById('workedDaysNote').textContent=s.manual?'Manual override is active.':(db.leave.some(l=>l.start<=`${YEAR}-${String(selected+1).padStart(2,'0')}-${String(new Date(YEAR,selected+1,0).getDate()).padStart(2,'0')}`&&l.end>=`${YEAR}-${String(selected+1).padStart(2,'0')}-01`)?'Auto-calculated: '+c.days+' actual Thu–Sun work days after excluding leave.':'Default paid working days: 18.5 (no leave in this month).');document.getElementById('slipMonth').textContent=MONTHS[selected]+' '+YEAR;document.getElementById('slipBase').textContent=money(s.active?s.base:0);document.getElementById('slipAllowance').textContent=money(s.active?num(s.daily)*c.days:0);document.getElementById('slipPhone').textContent=money(s.active?s.telephone:0);document.getElementById('slipOtherAllowances').textContent=money(s.active?c.otherAllowances:0);document.getElementById('slipGross').textContent=money(c.gross);document.getElementById('slipPension').textContent='−'+money(s.active?c.pension:0);document.getElementById('slipSocial').textContent='−'+money(s.active?s.social:0);document.getElementById('slipExtra').textContent='−'+money(s.active?num(s.extraDeduction):0);document.getElementById('slipNet').textContent=money(c.net)}
function renderLeave(){const rows=[...db.leave].sort((a,b)=>a.start.localeCompare(b.start));document.getElementById('leaveCount').textContent=rows.length+' periods';document.getElementById('leaveRows').innerHTML=rows.length?rows.map(l=>{let excluded=0;for(let d=new Date(l.start+'T12:00:00');d<=new Date(l.end+'T12:00:00');d.setDate(d.getDate()+1))if(!offDaysForMonth(d.getMonth()).includes(d.getDay()))excluded++;return `<tr><td><b>${escapeHtml(l.label||'Annual leave')}</b></td><td>${l.start}</td><td>${l.end}</td><td>${excluded}</td><td><button class="table-action" data-delete-leave="${l.id}">Remove</button></td></tr>`}).join(''):'<tr><td colspan="5" class="empty-state">No leave periods added yet.</td></tr>';document.getElementById('monthDaysGrid').innerHTML=MONTHS.map((m,i)=>`<div class="month-day-card"><span>${m}</span><b>${paidDays(i)}</b><small>paid working days</small></div>`).join('')}
function currentMonthExpenses(i){return db.months[i]?.expenses||[]}
function renderBudget(){const m=current(),c=calc(selected);document.getElementById('exchangeRate').value=m.budget.rate;document.getElementById('actualExchange').value=m.budget.actualExchange;['summarySalary','summaryUsdIncome','summaryMvrIncome','summaryMvrIncomeCover','summaryMvrSavingsUsed','summaryUsdExpenses','summaryUsdDebtExpenses','summaryMvrExpenses','summaryMvrDebtExpenses','summaryTotalExpenses','summaryAdditionalExchanges','summaryUsdSavings','summaryMvrSavings','summaryExchange'].forEach((id,k)=>{const v=[c.net,c.otherIncomeUsd-c.usdDebtIn+c.usdDebtIn,c.mvrIncomeTotal,c.mvrIncomeCover+c.mvrDebtCover,c.mvrSavingsUsed,c.usd,c.usdDebtOut,c.mvr,c.mvrDebtOut,c.expenses,c.additionalUsd,c.saved,c.mvrNetSaved,c.exchangeNeeded][k];const el=document.getElementById(id);if(el)el.textContent=['summaryMvrIncome','summaryMvrIncomeCover','summaryMvrSavingsUsed','summaryMvrExpenses','summaryMvrDebtExpenses','summaryMvrSavings'].includes(id)?mvr(v):money(v)});renderDebtTransactions();document.getElementById('expenseTableSubtitle').textContent=MONTHS[selected]+' '+YEAR;document.getElementById('expenseCount').textContent=m.expenses.length+' entries';document.getElementById('expenseDate').value=`${monthKey(selected)}-${String(new Date().getFullYear()===YEAR&&new Date().getMonth()===selected?new Date().getDate():1).padStart(2,'0')}`;renderAdditionalExchanges();document.getElementById('additionalExchangeDate').value=`${monthKey(selected)}-${String(new Date().getFullYear()===YEAR&&new Date().getMonth()===selected?new Date().getDate():1).padStart(2,'0')}`;document.getElementById('expenseRows').innerHTML=m.expenses.length?[...m.expenses].sort((a,b)=>b.date.localeCompare(a.date)).map(e=>{const equiv=e.currency==='USD'?num(e.amount):num(e.amount)/num(m.budget.rate);return `<tr><td>${e.date}</td><td><b>${escapeHtml(e.description)}</b></td><td>${escapeHtml(e.category)}</td><td>${e.currency==='USD'?money(e.amount):mvr(e.amount)}</td><td>${money(equiv)}</td><td><button class="table-action" data-edit-expense="${e.id}">Edit</button> <button class="table-action" data-delete-expense="${e.id}">Delete</button></td></tr>`}).join(''):'<tr><td colspan="6" class="empty-state">No expenses recorded for this month.</td></tr>'}
function mvrOpeningBalance(){return openingBalances().mvr}
function mvrBalanceThrough(i){let v=mvrOpeningBalance();for(let j=0;j<=i;j++)v+=calc(j).mvrNetSaved;return v}
function renderSavings(){const cs=all();let balance=openingBalances().usd,mvrBalance=mvrOpeningBalance();document.getElementById('savingsRows').innerHTML=cs.map((c,i)=>{balance+=c.saved;return `<tr><td><b>${MONTHS[i]}</b></td><td>${money(c.net+c.otherIncomeUsd)}</td><td>${money(c.expenses)}</td><td style="color:${c.saved>=0?'#13845b':'#bd5555'}"><b>${money(c.saved)}</b></td><td><b>${money(balance)}</b></td></tr>`}).join('');document.getElementById('mvrSavingsRows').innerHTML=cs.map((c,i)=>{const income=(db.months[i].otherIncome||[]).filter(x=>x.currency==='MVR').reduce((sum,x)=>sum+num(x.amount),0)+c.mvrDebtIn+c.exchangeSaved+c.exchangeCover;mvrBalance+=c.mvrNetSaved;return `<tr><td><b>${MONTHS[i]}</b></td><td>${mvr(income)}</td><td>${mvr(c.mvrCovered+c.mvrSavingsUsed)}</td><td>${mvr(c.mvrPersonalUsed)}</td><td><b>${mvr(c.mvrNetSaved)}</b></td><td><b>${mvr(mvrBalance)}</b></td></tr>`}).join('');document.getElementById('mvrSavedMonth').textContent=mvr(calculateMvrPositive(selected));document.getElementById('mvrSavedBalance').textContent=mvr(mvrBalanceThrough(selected));const total=cs.reduce((a,c)=>a+c.saved,0);document.getElementById('annualSaved').textContent=money(total);document.getElementById('currentBalance').textContent=money(openingBalances().usd+totalThrough(selected));document.getElementById('averageSaved').textContent=money(total/12);renderSavingsGoals()}
function calculateMvrPositive(i){const c=calc(i);return c.mvrNetSaved}
function renderDebtTransactions(){const rows=monthDebtPayments(selected),body=document.getElementById('debtTransactionRows');if(!body)return;document.getElementById('debtTxnCount').textContent=rows.length+' transactions';body.innerHTML=rows.length?rows.map(p=>`<tr><td>${p.date}</td><td>${p.debtType==='payable'?'Debt repayment':'Collection'}</td><td><b>${escapeHtml(p.person)}</b></td><td>${p.currency==='USD'?money(p.amount):mvr(p.amount)}</td><td>${p.currency==='MVR'&&p.debtType==='receivable'?mvr(p.coverMvr):'—'}</td><td>${p.currency==='MVR'&&p.debtType==='receivable'?mvr(num(p.amount)-num(p.coverMvr)):'—'}</td></tr>`).join(''):'<tr><td colspan="6" class="empty-state">No debt transactions recorded for this month.</td></tr>'}


function renderAdditionalExchanges(){const rows=current().additionalExchanges||[],body=document.getElementById('additionalExchangeRows');if(!body)return;document.getElementById('additionalExchangeCount').textContent=rows.length+' exchanges';body.innerHTML=rows.length?rows.map((e,i)=>{const purpose=e.purpose==='personal'?'Personal use / Emergency':e.purpose==='family'?'Family Support':'Other',allocation=e.purpose==='personal'?'Personal use / Emergency':e.allocation==='cover'?'Cover MVR expenses':e.allocation==='save'?'Save to MVR savings':'Personal use / Emergency';return `<tr><td><b>${i+1}</b></td><td>${e.date}</td><td>${money(e.usdAmount)}</td><td>${num(e.rate).toFixed(2)}</td><td>${mvr(e.mvrAmount)}</td><td>${purpose}</td><td>${allocation}${e.description?' · '+escapeHtml(e.description):''}</td><td><button class="table-action" data-edit-additional-exchange="${e.id}">Edit</button> <button class="table-action" data-delete-additional-exchange="${e.id}">Delete</button></td></tr>`}).join(''):'<tr><td colspan="8" class="empty-state">No additional exchanges recorded for this month.</td></tr>'}
function addAdditionalExchange(){const usdAmount=num(document.getElementById('additionalUsdAmount').value),date=document.getElementById('additionalExchangeDate').value,rate=num(document.getElementById('additionalExchangeRate').value),purpose=document.getElementById('additionalExchangePurpose').value,allocation=purpose==='personal'?'personal':document.getElementById('additionalExchangeAllocation').value,description=document.getElementById('additionalExchangeDescription').value.trim(),err=document.getElementById('additionalExchangeError');err.textContent='';if(usdAmount<=0||rate<=0){err.textContent='Enter a USD amount and exchange rate greater than zero.';return}if(!dateInYear(date)||Number(date.slice(5,7))!==selected+1){err.textContent='Choose a date in the selected month.';return}if(purpose==='other'&&!description){err.textContent='Add a description for an Other exchange.';return}const mvrAmount=usdAmount*rate;current().additionalExchanges.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),date,usdAmount,rate,mvrAmount,purpose,allocation,description});persist();['additionalUsdAmount','additionalExchangeRate','additionalExchangeDescription'].forEach(id=>document.getElementById(id).value='');renderAll();showToast('Additional exchange added to transactions')}
function editAdditionalExchange(id){const e=current().additionalExchanges.find(x=>x.id===id);if(!e)return;const usd=prompt('USD amount exchanged',String(e.usdAmount));if(usd===null)return;const rate=prompt('Exchange rate (MVR per USD)',String(e.rate));if(rate===null)return;const date=prompt('Date (YYYY-MM-DD)',e.date);if(date===null)return;const purpose=prompt('Purpose: personal, family, or other',e.purpose);if(purpose===null)return;const p=purpose.trim().toLowerCase();if(!['personal','family','other'].includes(p)){showToast('Purpose must be personal, family, or other');return}let allocation='personal';if(p!=='personal'){const a=prompt('Allocation: cover or save',e.allocation==='cover'?'cover':'save');if(a===null)return;allocation=a.trim().toLowerCase();if(!['cover','save'].includes(allocation)){showToast('Allocation must be cover or save');return}}const description=p==='other'?prompt('Description',e.description||''):'';if(description===null)return;const amount=num(usd),fx=num(rate);if(amount<=0||fx<=0||!dateInYear(date)||Number(date.slice(5,7))!==selected+1||(p==='other'&&!description.trim())){showToast('Invalid exchange details');return}Object.assign(e,{usdAmount:amount,rate:fx,mvrAmount:amount*fx,date,purpose:p,allocation,description:String(description||'').trim()});persist();renderAll();showToast('Additional exchange updated')}
function renderIncome(){const m=current(),rate=m.budget.rate,rows=m.otherIncome||[];document.getElementById('incomeDate').value=`${monthKey(selected)}-${String(new Date().getFullYear()===YEAR&&new Date().getMonth()===selected?new Date().getDate():1).padStart(2,'0')}`;document.getElementById('incomeRows').innerHTML=rows.length?[...rows].sort((a,b)=>b.date.localeCompare(a.date)).map(x=>{const covered=x.currency==='MVR'?Math.min(num(x.amount),Math.max(0,num(x.coverMvr))):0,saved=x.currency==='MVR'?Math.max(0,num(x.amount)-covered):0;return `<tr><td>${x.date}</td><td><b>${escapeHtml(x.description)}</b></td><td>${x.currency==='USD'?money(x.amount):mvr(x.amount)}</td><td>${x.currency==='USD'?money(x.amount):'—'}</td><td>${x.currency==='MVR'?mvr(covered):'—'}</td><td>${x.currency==='MVR'?mvr(saved):'—'}</td><td><button class="table-action" data-delete-income="${x.id}">Delete</button></td></tr>`}).join(''):'<tr><td colspan="7" class="empty-state">No other income recorded for this month.</td></tr>'}
function addIncome(){const description=document.getElementById('incomeDescription').value.trim(),amount=num(document.getElementById('incomeAmount').value),currency=document.getElementById('incomeCurrency').value,date=document.getElementById('incomeDate').value,err=document.getElementById('incomeError');err.textContent='';if(!description||amount<=0){err.textContent='Enter a source and an amount greater than zero.';return}if(!dateInYear(date)||Number(date.slice(5,7))!==selected+1){err.textContent='Choose a date in the selected month.';return}const coverMvr=currency==='MVR'?num(document.getElementById('incomeCoverMvr').value):0;if(coverMvr<0||coverMvr>amount){err.textContent='MVR used for expenses cannot exceed the MVR income amount.';return}const mvrExpenses=calc(selected).mvrTotalExpenses,alreadyCovered=calc(selected).mvrCovered+num(current().mvrSavingsUsed);if(coverMvr+alreadyCovered>mvrExpenses){err.textContent=`You can allocate up to ${mvr(mvrExpenses-alreadyCovered)} more, based on this month’s MVR expenses.`;return}current().otherIncome.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),description,amount,currency,date,coverMvr});persist();document.getElementById('incomeDescription').value='';document.getElementById('incomeAmount').value='';document.getElementById('incomeCoverMvr').value='0';renderAll();showToast(currency==='MVR'?(coverMvr>0?'MVR income allocated; remainder saved in MVR':'All MVR income saved'):'Other income added')}

function goalProgress(g,monthIndex=selected){if(g.type==='monthly')return num(g.contributions?.[monthKey(monthIndex)]);const startYear=Number(g.startYear||YEAR),startMonth=Number(g.startMonth||0),start=startYear*12+startMonth,end=start+Math.max(1,Number(g.months)||12)-1,at=YEAR*12+monthIndex;if(at<start)return 0;return Object.entries(g.contributions||{}).reduce((sum,[key,value])=>{const [yy,mm]=key.split('-').map(Number),n=yy*12+(mm-1);return n>=start&&n<=Math.min(end,at)?sum+num(value):sum},0);}
function goalStatus(g,progress){if(progress>=num(g.target))return 'Achieved';if(g.targetDate){const t=new Date(g.targetDate+'T23:59:59');if(t<new Date())return 'Past target date'}return 'In progress'}
function renderSavingsGoals(){const rows=document.getElementById('savingsGoalRows');if(!rows)return;const goals=db.savingsGoals||[];document.getElementById('goalMonthLabel').textContent=MONTHS[selected]+' '+YEAR;rows.innerHTML=goals.length?goals.map(g=>{const progress=goalProgress(g),target=num(g.target),pct=target>0?Math.min(100,progress/target*100):0,status=goalStatus(g,progress),currency=g.currency||'USD',fmt=currency==='USD'?money:mvr,period=g.type==='within'?`Within ${g.months||1} month(s)`:g.type==='yearly'?'Yearly':'Monthly';return `<div class="goal-card"><div class="goal-top"><div><b>${escapeHtml(g.name)}</b><small>${currency} · ${period}</small></div><span class="goal-status ${status==='Achieved'?'achieved':''}">${status}</span></div><div class="goal-progress-track"><div class="goal-progress-fill" style="width:${pct}%"></div></div><div class="goal-bottom"><b>${fmt(progress)} <span>of ${fmt(target)}</span></b><span>${pct.toFixed(0)}%</span></div><div class="goal-meta">Target date: ${g.targetDate||'Not set'}</div><div class="goal-actions"><button class="table-action" data-goal-contribute="${g.id}">Record contribution</button><button class="table-action" data-goal-delete="${g.id}">Delete goal</button></div></div>`}).join(''):'<div class="empty-state">Create a savings goal to start tracking progress.</div>'}
function addSavingsGoal(){const name=document.getElementById('goalName').value.trim(),type=document.getElementById('goalType').value,target=num(document.getElementById('goalTarget').value),currency=document.getElementById('goalCurrency').value,months=num(document.getElementById('goalMonths').value),targetDate=document.getElementById('goalTargetDate').value,err=document.getElementById('goalError');err.textContent='';if(!name||target<=0){err.textContent='Enter a goal name and a target amount greater than zero.';return}const now=new Date(YEAR,selected,1);if(type==='within')now.setMonth(now.getMonth()+months);else if(type==='yearly')now.setMonth(now.getMonth()+12);const computed=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(new Date(now.getFullYear(),now.getMonth()+1,0).getDate()).padStart(2,'0')}`;db.savingsGoals.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),name,type,target,currency,months:type==='within'?months:12,targetDate:targetDate||computed,startMonth:selected,startYear:YEAR,contributions:{}});persist();['goalName','goalTarget','goalTargetDate'].forEach(id=>document.getElementById(id).value='');renderSavingsGoals();showToast('Savings goal created')}
function recordGoalContribution(id){const g=db.savingsGoals.find(x=>x.id===id);if(!g)return;const fmt=g.currency==='MVR'?mvr:money,currentAmount=num(g.contributions?.[monthKey(selected)]),answer=prompt(`How much have you contributed to “${g.name}” in ${MONTHS[selected]}? (${g.currency||'USD'})`,String(currentAmount||''));if(answer===null)return;const amount=num(answer);if(amount<0){showToast('Enter zero or a positive amount');return}const available=g.currency==='MVR'?mvrBalanceThrough(selected):openingBalances().usd+totalThrough(selected);if(amount>available){showToast(`Contribution exceeds available ${g.currency||'USD'} savings`);return}if(!g.contributions)g.contributions={};g.contributions[monthKey(selected)]=amount;persist();renderSavingsGoals();showToast('Goal contribution saved')}

let debtView='active';
function debtCutoff(){return `${YEAR}-${String(selected+1).padStart(2,'0')}-${String(new Date(YEAR,selected+1,0).getDate()).padStart(2,'0')}`}
function paymentSumThrough(d,cutoff){const payments=Array.isArray(d.payments)?d.payments:[],recorded=payments.reduce((a,p)=>a+num(p.amount),0),legacy=Math.max(0,num(d.paidAmount)-recorded);return payments.filter(p=>(p.date||'')<=cutoff).reduce((a,p)=>a+num(p.amount),0)+((d.date||'')<=cutoff?legacy:0)}
function debtBalanceThrough(d,cutoff){if((d.date||'')>cutoff)return 0;return Math.max(0,num(d.amount)-paymentSumThrough(d,cutoff))}
function syncDebtPaid(d){const sum=(Array.isArray(d.payments)?d.payments:[]).reduce((a,p)=>a+num(p.amount),0);if(d.legacyPaid===undefined)d.legacyPaid=0;d.paidAmount=sum+num(d.legacyPaid);if(d.completed&&debtBalanceThrough(d,'9999-12-31')>0.005){d.completed=false;delete d.completedDate}}
function renderDebts(){const allRows=db.debts||[],cutoff=debtCutoff(),visible=allRows.filter(d=>(d.date||'')<=cutoff),active=allRows.filter(d=>!d.completed&&visible.includes(d)),completed=allRows.filter(d=>d.completed),rows=debtView==='completed'?completed:active;const sum=(type,currency)=>visible.filter(x=>x.type===type&&!x.completed&&x.currency===currency).reduce((a,x)=>a+debtBalanceThrough(x,cutoff),0);document.getElementById('debtOwedUsd').textContent=money(sum('payable','USD'));document.getElementById('debtOwedMvr').textContent=mvr(sum('payable','MVR'));document.getElementById('debtReceivableUsd').textContent=money(sum('receivable','USD'));document.getElementById('debtReceivableMvr').textContent=mvr(sum('receivable','MVR'));document.getElementById('debtCount').textContent=rows.length+' records';document.getElementById('completedDebtCount').textContent=completed.length;document.getElementById('debtMonthSubtitle').textContent=`Balances through ${cutoff}. Future-dated payments are excluded from this view.`;document.querySelectorAll('[data-debt-view]').forEach(b=>b.classList.toggle('active',b.dataset.debtView===debtView));document.getElementById('debtRows').innerHTML=rows.length?rows.map(x=>{const paid=paymentSumThrough(x,cutoff),balance=debtBalanceThrough(x,cutoff),fullyPaid=balance<0.005;return `<tr><td>${x.type==='payable'?'I owe':'Owed to me'}</td><td><b>${escapeHtml(x.person)}</b></td><td>${x.currency==='USD'?money(x.amount):mvr(x.amount)}</td><td>${x.currency==='USD'?money(paid):mvr(paid)}</td><td><b>${x.currency==='USD'?money(balance):mvr(balance)}</b></td><td>${escapeHtml(x.dueDate||'—')}</td><td>${escapeHtml(x.notes||'—')}</td><td class="debt-actions">${debtView==='active'?`<button class="table-action" data-debt-payment="${x.id}">Record payment</button> <button class="table-action" data-edit-debt="${x.id}">Edit</button> ${fullyPaid?`<button class="table-action" data-complete-debt="${x.id}">Mark completed</button>`:''}`:`<button class="table-action" data-edit-debt="${x.id}">Edit</button> <button class="table-action" data-reopen-debt="${x.id}">Move to active</button>`} <button class="table-action" data-delete-debt="${x.id}">Delete</button></td></tr>`}).join(''):`<tr><td colspan="8" class="empty-state">${debtView==='completed'?'No completed debts or loans yet.':'No active debts or loans recorded for this month.'}</td></tr>`;
 const history=allRows.flatMap(d=>(d.payments||[]).filter(p=>(p.date||'')<=cutoff).map(p=>({...p,debtId:d.id,person:d.person,type:d.type,currency:d.currency}))).sort((a,b)=>(b.date||'').localeCompare(a.date||''));document.getElementById('debtHistoryCount').textContent=history.length+' payments';document.getElementById('debtHistoryRows').innerHTML=history.length?history.map(p=>`<tr><td>${escapeHtml(p.date||'—')}</td><td><b>${escapeHtml(p.person)}</b></td><td>${p.type==='payable'?'Repayment':'Collection'}</td><td>${p.currency==='USD'?money(p.amount):mvr(p.amount)}</td><td>${p.currency==='MVR'&&p.type==='receivable'?mvr(p.coverMvr):'—'}</td><td><button class="table-action" data-edit-payment="${p.debtId}" data-payment-id="${p.id}">Edit</button> <button class="table-action" data-delete-payment="${p.debtId}" data-payment-id="${p.id}">Delete</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty-state">No payment history recorded yet.</td></tr>'}
function addDebt(){const type=document.getElementById('debtType').value,person=document.getElementById('debtPerson').value.trim(),amount=num(document.getElementById('debtAmount').value),currency=document.getElementById('debtCurrency').value,date=document.getElementById('debtDate').value||`${monthKey(selected)}-01`,dueDate=document.getElementById('debtDueDate').value,notes=document.getElementById('debtNotes').value.trim(),err=document.getElementById('debtError');err.textContent='';if(!person||amount<=0){err.textContent='Enter a person and an amount greater than zero.';return}if(!validISODate(date)||Number(date.slice(0,4))<2026||Number(date.slice(0,4))>2036){err.textContent='Enter a valid date between 2026 and 2036.';return}db.debts.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),type,person,amount,paidAmount:0,currency,date,dueDate,notes,payments:[],completed:false});persist();['debtPerson','debtAmount','debtDate','debtDueDate','debtNotes'].forEach(id=>document.getElementById(id).value='');renderAll();showToast('Debt record added')}
function editDebt(id){const d=db.debts.find(x=>x.id===id);if(!d)return;const person=prompt('Person / lender / borrower',d.person);if(person===null)return;const type=prompt('Record type: payable (I owe) or receivable (owed to me)',d.type);if(type===null)return;const amount=prompt('Original amount',String(d.amount));if(amount===null)return;const currency=prompt('Currency: USD or MVR',d.currency);if(currency===null)return;const date=prompt('Record date (YYYY-MM-DD)',d.date||`${monthKey(selected)}-01`);if(date===null)return;const due=prompt('Due date (YYYY-MM-DD, blank for none)',d.dueDate||'');if(due===null)return;const notes=prompt('Notes',d.notes||'');if(notes===null)return;const n=num(amount),cur=currency.trim().toUpperCase(),validDate=validISODate(date)&&Number(date.slice(0,4))>=2026&&Number(date.slice(0,4))<=2036&&(d.payments||[]).every(p=>(p.date||date)>=date);if(!person.trim()||n<=0||n<paymentSumThrough(d,'9999-12-31')||!['payable','receivable'].includes(type.trim())||!['USD','MVR'].includes(cur)||!validDate){showToast('Invalid debt details. Check type, name, amount, currency and date.');return}Object.assign(d,{person:person.trim(),type:type.trim(),amount:n,currency:cur,date,dueDate:due.trim(),notes:notes.trim()});syncDebtPaid(d);persist();renderAll();showToast('Debt record updated')}
function recordDebtPayment(id){const d=db.debts.find(x=>x.id===id);if(!d)return;const outstanding=debtBalanceThrough(d,'9999-12-31');const answer=prompt(`Enter ${d.type==='payable'?'repayment':'collection'} amount (${d.currency}). Outstanding: ${d.currency==='USD'?money(outstanding):mvr(outstanding)}`);if(answer===null)return;const amount=num(answer);if(amount<=0||amount>outstanding){showToast('Enter a valid amount up to the outstanding balance');return}const defaultDate=`${monthKey(selected)}-${String(Math.min(new Date().getDate(),new Date(YEAR,selected+1,0).getDate())).padStart(2,'0')}`,date=prompt('Transaction date (YYYY-MM-DD)',defaultDate);if(!date||!validISODate(date)||Number(date.slice(0,4))<2026||Number(date.slice(0,4))>2036||date<(d.date||'0000-01-01')){showToast('Enter a valid transaction date between 2026 and 2036');return}let coverMvr=0;if(d.type==='receivable'&&d.currency==='MVR'){const mi=Number(date.slice(5,7))-1;if(Number(date.slice(0,4))===YEAR&&mi>=0&&mi<12){const c=calc(mi),remaining=Math.max(0,c.mvrTotalExpenses-c.mvrCovered-num(db.months[mi].mvrSavingsUsed));const cover=prompt(`How much of this collection should cover MVR expenses? Enter 0 to save all. Maximum: ${mvr(Math.min(amount,remaining))}`,'0');if(cover===null)return;coverMvr=num(cover);if(coverMvr<0||coverMvr>amount||coverMvr>remaining){showToast('Invalid MVR expense allocation');return}}}if(!Array.isArray(d.payments))d.payments=[];d.payments.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),date,amount,coverMvr});syncDebtPaid(d);persist();renderAll();showToast('Payment recorded')}
function editDebtPayment(debtId,paymentId){const d=db.debts.find(x=>x.id===debtId),p=d?.payments?.find(x=>x.id===paymentId);if(!p)return;const date=prompt('Payment date (YYYY-MM-DD)',p.date);if(date===null)return;const amount=prompt('Payment amount',String(p.amount));if(amount===null)return;const cover=prompt('MVR amount used for expenses (0 if not applicable)',String(num(p.coverMvr)));if(cover===null)return;const n=num(amount),c=num(cover),maxAllowed=debtBalanceThrough(d,'9999-12-31')+num(p.amount);if(!validISODate(date)||Number(date.slice(0,4))<2026||Number(date.slice(0,4))>2036||date<(d.date||'0000-01-01')||n<=0||n>maxAllowed||c<0||c>n){showToast('Invalid payment details');return}p.date=date;p.amount=n;p.coverMvr=c;syncDebtPaid(d);persist();renderAll();showToast('Payment updated')}
function deleteDebtPayment(debtId,paymentId){const d=db.debts.find(x=>x.id===debtId);if(!d||!confirm('Delete this payment transaction? The outstanding balance will be recalculated.'))return;d.payments=(d.payments||[]).filter(p=>p.id!==paymentId);syncDebtPaid(d);persist();renderAll();showToast('Payment deleted and balance recalculated')}

function useMvrSavings(){const amount=num(document.getElementById('mvrSavingsUseAmount').value),purpose=document.getElementById('mvrSavingsUsePurpose').value,available=Math.max(0,mvrBalanceThrough(selected));if(amount<=0){showToast('Enter an amount greater than zero');return}if(amount>available){showToast(`Available MVR savings: ${mvr(available)}`);return}if(purpose==='cover'){const maxNeed=Math.max(0,calc(selected).mvrTotalExpenses-calc(selected).mvrCovered-num(current().mvrSavingsUsed));if(amount>maxNeed){showToast(`MVR expenses remaining after other cover: ${mvr(maxNeed)}`);return}current().mvrSavingsUsed=num(current().mvrSavingsUsed)+amount}else{current().mvrPersonalUsed=num(current().mvrPersonalUsed)+amount}persist();document.getElementById('mvrSavingsUseAmount').value='';renderAll();showToast(purpose==='cover'?'MVR savings applied to expenses':'MVR savings withdrawn for personal use')}

function renderReports(){const cs=all();let income=0,expenses=0,savings=0;cs.forEach((c,i)=>{if(i<=selected){const fx=num(db.months[i].budget.rate)||DEFAULTS.rate;income+=c.totalIncome+c.mvrIncomeTotal/fx;expenses+=c.expenses;savings+=c.saved+c.mvrNetSaved/fx}});document.getElementById('reportIncome').textContent=money(income);document.getElementById('reportExpenses').textContent=money(expenses);document.getElementById('reportRate').textContent=income?((savings/income)*100).toFixed(1)+'%':'0%';const rows=document.getElementById('reportRows');if(rows)rows.innerHTML=cs.map((c,i)=>`<tr><td><b>${MONTHS[i]}</b></td><td>${c.days}</td><td>${money(c.net)}</td><td>${money(c.usdExpenses)}</td><td>${mvr(c.mvrTotalExpenses)}</td><td>${money(c.saved+c.mvrNetSaved/(num(db.months[i].budget.rate)||DEFAULTS.rate))}</td></tr>`).join('');const sel=document.getElementById('reportMonth');if(sel)sel.value=String(selected)}

function renderSettings(){const d=db.defaults;const eff=document.getElementById('offDaysEffectiveMonth');if(eff){eff.innerHTML=MONTHS.map((m,i)=>`<option value="${i}">${m} ${YEAR}</option>`).join('');eff.value=selected}const days=offDaysForMonth(selected);document.querySelectorAll('#offDayPicker input').forEach(x=>x.checked=days.includes(Number(x.value)));const display=document.getElementById('weekdayRuleDisplay');if(display)display.innerHTML=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((d,i)=>`<span class="${days.includes(i)?'offday':'workday'}">${d.slice(0,3).toUpperCase()}<br><small>${days.includes(i)?'Off':'Work'}</small></span>`).join('');['defaultBase','defaultDaily','defaultPhone','defaultPension','defaultSocial','defaultRate'].forEach((id,i)=>document.getElementById(id).value=[d.base,d.daily,d.telephone,d.pension,d.social,d.rate][i])}
function renderAll(){document.getElementById('topMonth').textContent=MONTHS[selected]+' '+YEAR;renderDashboard();renderSalary();renderLeave();renderBudget();renderIncome();renderSavings();renderDebts();renderReports();renderSettings()}
function saveSalary(){const s=current().salary;s.base=num(document.getElementById('basePay').value);s.daily=num(document.getElementById('dailyRate').value);s.telephone=num(document.getElementById('telephone').value);s.pension=num(document.getElementById('pensionRate').value);s.social=num(document.getElementById('socialFund').value);s.extraDeduction=num(document.getElementById('extraDeduction').value);s.otherAllowances=num(document.getElementById('otherAllowances').value);s.manual=document.getElementById('manualDays').checked;s.daysOverride=s.manual?num(document.getElementById('workedDays').value):null;s.active=true;delete s.pendingDefaults;persist();renderAll();showToast('Salary settings saved')}
function saveBudget(){const rate=num(document.getElementById('exchangeRate').value);if(rate<=0){showToast('Enter a valid exchange rate');return}current().budget.rate=rate;current().budget.actualExchange=document.getElementById('actualExchange').value;persist();renderAll();showToast('Exchange settings saved')}
function addLeave(){const start=document.getElementById('leaveStart').value,end=document.getElementById('leaveEnd').value,err=document.getElementById('leaveError');err.textContent='';if(!dateInYear(start)||!dateInYear(end)){err.textContent='Choose valid dates within '+YEAR+'.';return}if(end<start){err.textContent='The end date must be on or after the start date.';return}if(db.leave.some(l=>start<=l.end&&end>=l.start)){err.textContent='This period overlaps an existing leave period. Edit your dates to avoid overlap.';return}db.leave.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),start,end,label:document.getElementById('leaveLabel').value.trim()||'Annual leave'});persist();document.getElementById('leaveStart').value='';document.getElementById('leaveEnd').value='';document.getElementById('leaveLabel').value='';renderAll();showToast('Leave period added; working days recalculated')}
function addExpense(){const desc=document.getElementById('expenseDescription').value.trim(),amount=num(document.getElementById('expenseAmount').value),currency=document.getElementById('expenseCurrency').value,date=document.getElementById('expenseDate').value,err=document.getElementById('expenseError');err.textContent='';if(!desc||amount<=0){err.textContent='Enter a description and an amount greater than zero.';return}if(!dateInYear(date)||Number(date.slice(5,7))!==selected+1){err.textContent='Choose a date in the selected month of '+YEAR+'.';return}current().expenses.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),description:desc,category:document.getElementById('expenseCategory').value,amount,currency,date});persist();document.getElementById('expenseDescription').value='';document.getElementById('expenseAmount').value='';renderAll();showToast('Expense added')}
function exportFile(obj,name,type='application/json'){const blob=new Blob([type==='text/csv'?obj:JSON.stringify(obj,null,2)],{type:type==='text/csv'?'text/csv':'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
function exportCsv(){const rows=[['Month','Paid working days','Gross salary USD','Net salary USD','Other income USD','Total income USD','USD expenses','Additional exchanges USD','MVR expenses','MVR covered','MVR personal use','MVR saved / net movement','MVR expense USD equivalent','Total expenses USD','Savings USD','Running balance USD']];let balance=openingBalances().usd;all().forEach((c,i)=>{balance+=c.saved;rows.push([MONTHS[i],c.days,c.gross,c.net,c.otherIncomeUsd,c.totalIncome,c.usd,c.additionalUsd,c.mvr,c.mvrCovered,c.mvrPersonalUsed,c.mvrNetSaved,c.mvrUsd,c.expenses,c.saved,balance])});const csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n');exportFile(csv,`personal-finance-${YEAR}-report.csv`,'text/csv')}

/* Forecast builder: forecasts are stored separately from actual monthly records. */
const FORECAST_KEY='personalFinanceForecasts_v1';
let activeForecast=null;
function readForecasts(){try{const x=JSON.parse(localStorage.getItem(FORECAST_KEY)||'[]');return Array.isArray(x)?x:[]}catch(e){return []}}
function writeForecasts(list){localStorage.setItem(FORECAST_KEY,JSON.stringify(list))}
function getYearRecord(y){try{const x=JSON.parse(localStorage.getItem(`ameerFinancePWA${y}_v1`)||'null');if(x&&x.year===y&&Array.isArray(x.months))return x}catch(e){}return null}
function forecastDefaults(y,rec){if(rec?.defaults)return {...DEFAULTS,...rec.defaults};for(let py=y-1;py>=2026;py--){const prior=getYearRecord(py);if(prior?.defaults)return {...DEFAULTS,...prior.defaults}}return {...DEFAULTS}}
function forecastOffDays(y,mi,rec){const changes=Array.isArray(rec?.offDayChanges)?rec.offDayChanges:[];const applicable=changes.filter(c=>Number(c.month)<=mi).sort((a,b)=>a.month-b.month);if(applicable.length)return applicable[applicable.length-1].days||[1,2,3];for(let py=y-1;py>=2026;py--){const prev=getYearRecord(py),pcs=Array.isArray(prev?.offDayChanges)?prev.offDayChanges:[];if(pcs.length)return [...pcs.sort((a,b)=>a.month-b.month).at(-1).days]}return [1,2,3]}
function forecastMonthDays(y,mi,rec,month){const salary=month?.salary||{},start=`${y}-${String(mi+1).padStart(2,'0')}-01`,end=`${y}-${String(mi+1).padStart(2,'0')}-${String(new Date(y,mi+1,0).getDate()).padStart(2,'0')}`,leaves=Array.isArray(rec?.leave)?rec.leave:[],hasLeave=leaves.some(l=>l.start<=end&&l.end>=start);if(salary.manual)return Math.max(0,num(salary.daysOverride));if(!hasLeave)return 18.5;const off=forecastOffDays(y,mi,rec);let count=0;for(let d=1;d<=new Date(y,mi+1,0).getDate();d++){const date=`${y}-${String(mi+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,weekday=new Date(y,mi,d).getDay();if(!off.includes(weekday)&&!leaves.some(l=>date>=l.start&&date<=l.end))count++}return count}
function forecastSalaryFromRecord(y,mi,rec){const defaults=forecastDefaults(y,rec),saved=rec?.months?.[mi]?.salary||{},savedHasValues=['base','daily','telephone','pension','social','extraDeduction','otherAllowances'].some(k=>num(saved[k])!==0),hasSaved=saved.active===true||(saved.active===undefined&&savedHasValues),src=hasSaved?saved:defaults,hasDefaultValues=['base','daily','telephone','pension','social','extraDeduction','otherAllowances'].some(k=>num(src[k])!==0);return {base:num(src.base),daily:num(src.daily),telephone:num(src.telephone),pension:num(src.pension),social:num(src.social),extraDeduction:num(src.extraDeduction),otherAllowances:num(src.otherAllowances),active:hasSaved||(!hasSaved&&hasDefaultValues)}}
function forecastBuild(start,end,average,existing=null){const [sy,sm]=start.split('-').map(Number),[ey,em]=end.split('-').map(Number),startIndex=sy*12+sm-1,endIndex=ey*12+em-1,count=endIndex-startIndex+1;if(count<1||count>60)throw Error('Choose a valid range of 1 to 60 months (maximum five years).');if(sy<2026||ey>2036)throw Error('Forecast dates must be within the app’s supported years (2026–2036).');const rows=[],changes=(existing?.salaryChanges||[]).map(c=>({...c,index:Number(c.index)})).sort((a,b)=>a.index-b.index),expenseOverrides=existing?.expenseOverrides||{},workingDayOverrides=existing?.workingDayOverrides||{};for(let k=0;k<count;k++){const index=startIndex+k,y=Math.floor(index/12),mi=index%12,rec=getYearRecord(y),month=rec?.months?.[mi]||null;const change=changes.filter(c=>c.index<=index).at(-1);let salary=change&&change.type!=='net'?{...change.salary}:forecastSalaryFromRecord(y,mi,rec);let days=Object.prototype.hasOwnProperty.call(workingDayOverrides,index)?Math.max(0,num(workingDayOverrides[index])):forecastMonthDays(y,mi,rec,month);const pension=salary.active?num(salary.base)*num(salary.pension)/100:0,gross=salary.active?num(salary.base)+num(salary.daily)*num(days)+num(salary.telephone)+num(salary.otherAllowances):0,calculatedNet=salary.active?gross-pension-num(salary.social)-num(salary.extraDeduction):0;const income=change?.type==='net'?num(change.netIncome):calculatedNet;const key=`${y}-${String(mi+1).padStart(2,'0')}`,expenses=Object.prototype.hasOwnProperty.call(expenseOverrides,key)?Math.max(0,num(expenseOverrides[key])):Math.max(0,num(average));rows.push({key,year:y,month:mi,monthLabel:`${MONTHS[mi]} ${y}`,days,income,expenses,savings:income-expenses,salary:{...salary},manualNet:change?.type==='net'})}return {id:existing?.id||`forecast-${Date.now()}`,name:existing?.name||`${MONTHS[sm-1]} ${sy} – ${MONTHS[em-1]} ${ey}`,start,end,averageExpenses:num(average),salaryChanges:changes,expenseOverrides,workingDayOverrides,rows,updatedAt:new Date().toISOString()}}
function forecastTotals(f){return f.rows.reduce((a,r)=>({income:a.income+r.income,expenses:a.expenses+r.expenses,savings:a.savings+r.savings}),{income:0,expenses:0,savings:0})}
function renderForecast(f){activeForecast=f;const wrap=document.getElementById('forecastReport');if(!f){wrap.hidden=true;document.getElementById('forecastActions').hidden=true;return}wrap.hidden=false;document.getElementById('forecastActions').hidden=false;const t=forecastTotals(f);document.getElementById('forecastMonths').textContent=f.rows.length;document.getElementById('forecastIncome').textContent=money(t.income);document.getElementById('forecastExpenses').textContent=money(t.expenses);document.getElementById('forecastSavings').textContent=money(t.savings);document.getElementById('forecastIncomeTotal').textContent=money(t.income);document.getElementById('forecastExpensesTotal').textContent=money(t.expenses);document.getElementById('forecastSavingsTotal').textContent=money(t.savings);document.getElementById('forecastDaysTotal').textContent=f.rows.reduce((a,r)=>a+r.days,0).toFixed(1);document.getElementById('forecastRows').innerHTML=f.rows.map((r,i)=>`<tr><td><b>${escapeHtml(r.monthLabel)}</b></td><td>${r.days.toFixed(1)}${Object.prototype.hasOwnProperty.call(f.workingDayOverrides,r.year*12+r.month)?' <small class="muted">(edited)</small>':''}</td><td>${money(r.income)}${r.manualNet?' <small class="muted">(manual)</small>':''}</td><td>${money(r.expenses)}</td><td>${money(r.savings)}</td><td><div class="forecast-row-actions"><button data-forecast-days="${i}">Edit working days</button><button data-forecast-salary="${i}">Edit salary for the month</button><button data-forecast-expense="${i}">Edit expenses</button></div></td></tr>`).join('');refreshSavedForecasts()}
function refreshSavedForecasts(){const sel=document.getElementById('savedForecastSelect');if(!sel)return;const saved=readForecasts(),chosen=sel.value;sel.innerHTML='<option value="">Choose a saved forecast</option>'+saved.map(f=>`<option value="${escapeHtml(f.id)}">${escapeHtml(f.name||'Saved forecast')}</option>`).join('');if(saved.some(f=>f.id===chosen))sel.value=chosen}
function generateForecast(){const start=document.getElementById('forecastStart').value,end=document.getElementById('forecastEnd').value,rawAverage=document.getElementById('forecastAverageExpenses').value,average=num(rawAverage),err=document.getElementById('forecastError');err.textContent='';try{if(!start||!end)throw Error('Choose both a starting month and an ending month.');if(rawAverage.trim()===''||!Number.isFinite(Number(rawAverage))||average<0)throw Error('Enter a valid non-negative average monthly expense in USD.');const f=forecastBuild(start,end,average);renderForecast(f)}catch(e){err.textContent=e.message}}
function forecastModal(title,fields,onSave,description='Changes apply only as described for this forecast row.'){
 let overlay=document.getElementById('forecastEditModal');if(overlay)overlay.remove();
 overlay=document.createElement('div');overlay.id='forecastEditModal';overlay.className='forecast-modal-backdrop';
 overlay.innerHTML=`<form class="forecast-modal" role="dialog" aria-modal="true" aria-labelledby="forecastModalTitle"><div class="panel-head"><div><h2 id="forecastModalTitle">${escapeHtml(title)}</h2><p class="muted">${escapeHtml(description)}</p></div><button type="button" class="btn secondary" data-close>Close</button></div><div class="form-grid">${fields.map((f,i)=>`<label>${escapeHtml(f.label)}<input name="f${i}" type="number" step="${f.step||'0.01'}" min="${f.min??0}" value="${escapeHtml(String(f.value))}" required></label>`).join('')}</div><div class="button-row"><button class="btn primary" type="submit">Save changes</button><button class="btn secondary" type="button" data-close>Cancel</button></div></form>`;
 document.body.appendChild(overlay);const close=()=>overlay.remove();overlay.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',close));overlay.addEventListener('click',e=>{if(e.target===overlay)close()});
 overlay.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const vals=fields.map((f,i)=>{const raw=overlay.querySelector(`[name="f${i}"]`).value;return raw.trim()===''?NaN:Number(raw)});if(vals.some((v,i)=>!Number.isFinite(v)||v<(fields[i].min??0))){showToast('Enter valid non-negative values in every field.');return}const result=onSave(vals);if(result!==false)close()});overlay.querySelector('input')?.focus();
}
function forecastConfirm(title,message,confirmLabel,onConfirm){let overlay=document.getElementById('forecastConfirmModal');if(overlay)overlay.remove();overlay=document.createElement('div');overlay.id='forecastConfirmModal';overlay.className='forecast-modal-backdrop';overlay.innerHTML=`<section class="forecast-modal" role="dialog" aria-modal="true"><div class="panel-head"><div><h2>${escapeHtml(title)}</h2><p class="muted">${escapeHtml(message)}</p></div><button type="button" class="btn secondary" data-close>Close</button></div><div class="button-row"><button type="button" class="btn primary" data-confirm>${escapeHtml(confirmLabel)}</button><button type="button" class="btn secondary" data-close>Cancel</button></div></section>`;document.body.appendChild(overlay);const close=()=>overlay.remove();overlay.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',close));overlay.addEventListener('click',e=>{if(e.target===overlay)close()});overlay.querySelector('[data-confirm]').addEventListener('click',()=>{onConfirm();close()})}
function editForecastWorkingDays(rowIndex){if(!activeForecast)return;const row=activeForecast.rows[rowIndex],index=row.year*12+row.month;forecastModal(`Edit working days — ${row.monthLabel}`,[{label:'Working days',value:row.days,step:'0.5'}],([days])=>{activeForecast.workingDayOverrides[index]=days;activeForecast=forecastBuild(activeForecast.start,activeForecast.end,activeForecast.averageExpenses,activeForecast);renderForecast(activeForecast);showToast('Working days updated for '+row.monthLabel)},'This override applies to this month only. Other months keep their own saved or calculated working days.')}
function editForecastSalary(rowIndex){if(!activeForecast)return;const row=activeForecast.rows[rowIndex],salaryNow=row.salary,index=row.year*12+row.month;const applySalary=vals=>{const [base,daily,telephone,pension,social,extraDeduction,otherAllowances]=vals;if(pension>100){showToast('Pension must be 100% or less.');return false}const salary={base,daily,telephone,pension,social,extraDeduction,otherAllowances,active:true};activeForecast.salaryChanges=activeForecast.salaryChanges.filter(c=>c.index<index);activeForecast.salaryChanges.push({index,type:'salary',salary});activeForecast=forecastBuild(activeForecast.start,activeForecast.end,activeForecast.averageExpenses,activeForecast);renderForecast(activeForecast);showToast('Salary recalculated and applied from '+row.monthLabel+' onward')};
 forecastModal(`Edit salary for the month — ${row.monthLabel}`,[{label:'Base salary (USD)',value:salaryNow.base},{label:'Daily allowance (USD)',value:salaryNow.daily},{label:'Telephone allowance (USD)',value:salaryNow.telephone},{label:'Pension (%)',value:salaryNow.pension},{label:'Social fund deduction (USD)',value:salaryNow.social},{label:'Additional deduction (USD)',value:salaryNow.extraDeduction},{label:'Other allowances (USD)',value:salaryNow.otherAllowances}],applySalary,'Enter the salary-sheet components. Net income is recalculated using this month’s working days and carries forward through the rest of the forecast.');
 const modal=document.getElementById('forecastEditModal'),form=modal?.querySelector('form');if(form){const manual=document.createElement('button');manual.type='button';manual.className='btn secondary';manual.textContent='Enter net income instead';manual.addEventListener('click',()=>{modal.remove();forecastModal(`Enter net income — ${row.monthLabel}`,[{label:'Net income (USD)',value:row.income}],([netIncome])=>{activeForecast.salaryChanges=activeForecast.salaryChanges.filter(c=>c.index<index);activeForecast.salaryChanges.push({index,type:'net',netIncome});activeForecast=forecastBuild(activeForecast.start,activeForecast.end,activeForecast.averageExpenses,activeForecast);renderForecast(activeForecast);showToast('Net income set for '+row.monthLabel+' and all following forecast months')},'This value replaces the calculated net income from this month through the end of the forecast.')});form.querySelector('.button-row').prepend(manual)}}
function editForecastExpense(rowIndex){if(!activeForecast)return;const row=activeForecast.rows[rowIndex];forecastModal(`Edit expenses — ${row.monthLabel}`,[{label:'Expenses (USD)',value:row.expenses}],([amount])=>{activeForecast.expenseOverrides[row.key]=amount;activeForecast=forecastBuild(activeForecast.start,activeForecast.end,activeForecast.averageExpenses,activeForecast);renderForecast(activeForecast);showToast('Expenses updated for '+row.monthLabel)},'This changes expenses for this month only. Other months keep their current expense values.')}
function saveForecast(){if(!activeForecast)return;let overlay=document.getElementById('forecastNameModal');if(overlay)overlay.remove();overlay=document.createElement('div');overlay.id='forecastNameModal';overlay.className='forecast-modal-backdrop';overlay.innerHTML=`<form class="forecast-modal" role="dialog" aria-modal="true"><div class="panel-head"><div><h2>Save forecast</h2><p class="muted">Choose a name so you can find this forecast later.</p></div><button type="button" class="btn secondary" data-close>Close</button></div><label>Forecast name<input name="forecastName" type="text" maxlength="80" required value="${escapeHtml(activeForecast.name)}"></label><div class="button-row"><button class="btn primary" type="submit">Save forecast</button><button class="btn secondary" type="button" data-close>Cancel</button></div></form>`;document.body.appendChild(overlay);const close=()=>overlay.remove();overlay.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',close));overlay.addEventListener('click',e=>{if(e.target===overlay)close()});overlay.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const name=overlay.querySelector('[name=forecastName]').value.trim();if(!name){showToast('Enter a forecast name.');return}activeForecast.name=name;const list=readForecasts(),at=list.findIndex(f=>f.id===activeForecast.id);if(at>=0)list[at]=activeForecast;else list.push(activeForecast);writeForecasts(list);refreshSavedForecasts();document.getElementById('savedForecastSelect').value=activeForecast.id;close();showToast('Forecast saved in this app')});overlay.querySelector('input')?.focus()}
function loadSavedForecast(){const id=document.getElementById('savedForecastSelect').value,f=readForecasts().find(x=>x.id===id);if(!f){showToast('Choose a saved forecast first');return}document.getElementById('forecastStart').value=f.start;document.getElementById('forecastEnd').value=f.end;document.getElementById('forecastAverageExpenses').value=f.averageExpenses;renderForecast(f)}
function exportForecastCsv(){if(!activeForecast)return;const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"',rows=[['Month','Working days','Income (USD)','Expenses (USD)','Savings (USD)'],...activeForecast.rows.map(r=>[r.monthLabel,r.days.toFixed(1),r.income.toFixed(2),r.expenses.toFixed(2),r.savings.toFixed(2)])],t=forecastTotals(activeForecast);rows.push(['TOTAL','',t.income.toFixed(2),t.expenses.toFixed(2),t.savings.toFixed(2)]);exportFile(rows.map(r=>r.map(q).join(',')).join('\r\n'),`forecast-${activeForecast.start}-to-${activeForecast.end}.csv`,'text/csv')}
